package simple_test

import (
	"encoding/json"
	"math"
	"net/http"
	"net/http/httptest"
	"net/url"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"testing"

	"github.com/xantiagoma/xtandard-image/internal/dialect"
	"github.com/xantiagoma/xtandard-image/internal/dialect/router"
	"github.com/xantiagoma/xtandard-image/internal/dialect/simple"
	"github.com/xantiagoma/xtandard-image/internal/transform"
)

// fixtureDir holds one unpic fixture file per provider, generated by
// tools/compat/unpic/generate.ts.
const fixtureDir = "../../../tools/compat/unpic"

// relativeHost is the request host for relative fixture URLs.
const relativeHost = "xi.test"

type fixtureFile struct {
	Provider string `json:"provider"`
	Mode     string `json:"mode"`
	Fixtures []struct {
		URL    string `json:"url"`
		Origin string `json:"origin"`
		Want   struct {
			Width   *float64 `json:"width"`
			Height  *float64 `json:"height"`
			Format  *string  `json:"format"`
			Quality *float64 `json:"quality"`
			Source  string   `json:"source"`
		} `json:"want"`
	} `json:"fixtures"`
}

func loadFixtures(tb testing.TB) map[string]*fixtureFile {
	tb.Helper()
	paths, err := filepath.Glob(filepath.Join(fixtureDir, "*.json"))
	if err != nil || len(paths) == 0 {
		tb.Fatalf("no fixtures in %s: %v", fixtureDir, err)
	}
	out := make(map[string]*fixtureFile, len(paths))
	for _, p := range paths {
		data, err := os.ReadFile(p)
		if err != nil {
			tb.Fatal(err)
		}
		var f fixtureFile
		if err := json.Unmarshal(data, &f); err != nil {
			tb.Fatalf("%s: %v", p, err)
		}
		out[f.Provider] = &f
	}
	return out
}

// hostsOf returns the hosts of the absolute fixture URLs.
func hostsOf(tb testing.TB, files ...*fixtureFile) []string {
	tb.Helper()
	var hosts []string
	for _, f := range files {
		for _, fx := range f.Fixtures {
			u, err := url.Parse(fx.URL)
			if err != nil {
				tb.Fatal(err)
			}
			if u.Host != "" && !slices.Contains(hosts, u.Host) {
				hosts = append(hosts, u.Host)
			}
		}
	}
	return hosts
}

func newRouter(tb testing.TB, enabled, hosts []string) *router.Router {
	tb.Helper()
	dialects, mounts, err := simple.Mounts(&simple.MountOptions{Enabled: enabled, Hosts: hosts, Source: "origin"})
	if err != nil {
		tb.Fatal(err)
	}
	rt, err := router.New(&router.Options{Mounts: mounts, Policy: router.PolicyAllow}, dialects)
	if err != nil {
		tb.Fatal(err)
	}
	return rt
}

func route(tb testing.TB, rt *router.Router, rawURL string) (*dialect.Result, error) {
	tb.Helper()
	u, err := url.Parse(rawURL)
	if err != nil {
		tb.Fatalf("%s: %v", rawURL, err)
	}
	req := httptest.NewRequestWithContext(tb.Context(), http.MethodGet, "/", nil)
	req.URL, req.Host = u, u.Host
	if u.Host == "" {
		req.Host = relativeHost
	}
	res, _, err := rt.Route(req)
	return res, err
}

// wantFormat maps unpic's format names; ok is false for names xi does not
// encode (the parser records them as ignored).
func wantFormat(s string) (transform.Format, bool) {
	switch strings.ToLower(s) {
	case "jpg", "jpeg", "pjpg":
		return transform.FormatJPEG, true
	case "png", "png8":
		return transform.FormatPNG, true
	case "webp":
		return transform.FormatWebP, true
	case "avif":
		return transform.FormatAVIF, true
	case "gif":
		return transform.FormatGIF, true
	case "auto", "origin", "":
		return transform.FormatUnset, true
	}
	return transform.FormatUnset, false
}

func round(f *float64) int {
	if f == nil {
		return 0
	}
	return int(math.Round(*f))
}

func unescape(s string) string {
	if u, err := url.PathUnescape(s); err == nil {
		return u
	}
	return s
}

// TestUnpicFixtures routes every unpic fixture of every simple provider
// through a router with only that provider enabled (native prefixes plus
// a host binding on the fixture hosts) and checks that xi reads the same
// width, height, format, quality and source as unpic's extract(). Width
// and height are always compared (absent = auto); format and quality when
// unpic reports them (xi also reads provider options unpic does not map,
// such as ImageEngine cmpr).
func TestUnpicFixtures(t *testing.T) {
	t.Parallel()
	files := loadFixtures(t)
	for _, spec := range simple.Providers() {
		t.Run(spec.Name, func(t *testing.T) {
			t.Parallel()
			f, ok := files[spec.Name]
			if !ok {
				t.Fatalf("no fixture file %s/%s.json: run tools/compat/unpic/generate.ts", fixtureDir, spec.Name)
			}
			if len(f.Fixtures) == 0 {
				t.Fatal("empty fixture file")
			}
			rt := newRouter(t, []string{spec.Name}, hostsOf(t, f))
			for _, fx := range f.Fixtures {
				res, err := route(t, rt, fx.URL)
				if err != nil {
					t.Errorf("%s: %v", fx.URL, err)
					continue
				}
				r := res.Request
				pl := &r.Pipelines[0]
				if got, want := pl.Resize.Width.Px, round(fx.Want.Width); got != want {
					t.Errorf("%s: width %d, unpic %d", fx.URL, got, want)
				}
				if got, want := pl.Resize.Height.Px, round(fx.Want.Height); got != want {
					t.Errorf("%s: height %d, unpic %d", fx.URL, got, want)
				}
				if fx.Want.Quality != nil && r.Output.Quality != round(fx.Want.Quality) {
					t.Errorf("%s: quality %d, unpic %v", fx.URL, r.Output.Quality, *fx.Want.Quality)
				}
				if fx.Want.Format != nil {
					if want, ok := wantFormat(*fx.Want.Format); ok && r.Output.Format != want {
						t.Errorf("%s: format %v, unpic %q", fx.URL, r.Output.Format, *fx.Want.Format)
					}
				}
				if got, want := unescape(res.SourceString), unescape(fx.Want.Source); got != want {
					t.Errorf("%s: source %q, unpic %q", fx.URL, got, want)
				}
				for _, ig := range r.Ignored {
					if ig.Reason == "unknown option" {
						t.Errorf("%s: unpic writes %q, which the table does not know", fx.URL, ig.Option)
					}
				}
				if res.SourceString != r.Source.Raw {
					t.Errorf("%s: SourceString %q != Source.Raw %q", fx.URL, res.SourceString, r.Source.Raw)
				}
				if r.Source.Encoding == transform.SourceRelative && r.Source.Mount != "origin" {
					t.Errorf("%s: relative source not bound to the mount source: %q", fx.URL, r.Source.Mount)
				}
				r.ApplyDefaults(transform.StandardDefaults())
				if err := r.Validate(); err != nil {
					t.Errorf("%s: invalid request: %v", fx.URL, err)
				}
			}
		})
	}
}

// TestUnpicDetection enables every provider at once, host-binds the family
// to every fixture host, and checks each fixture reaches its own provider
// (native prefix, then upstream domain).
func TestUnpicDetection(t *testing.T) {
	t.Parallel()
	files := loadFixtures(t)
	names := make([]string, 0, len(simple.Providers()))
	var own []*fixtureFile
	for _, spec := range simple.Providers() {
		names = append(names, spec.Name)
		if f, ok := files[spec.Name]; ok {
			own = append(own, f)
		}
	}
	rt := newRouter(t, names, hostsOf(t, own...))
	for _, f := range own {
		for _, fx := range f.Fixtures {
			res, err := route(t, rt, fx.URL)
			if err != nil {
				t.Errorf("%s: %v", fx.URL, err)
				continue
			}
			if got, want := res.Request.Dialect, simple.Name+":"+f.Provider; got != want {
				t.Errorf("%s: routed to %s, want %s", fx.URL, got, want)
			}
		}
	}
}
